function v22TableAbstractQ(model){
  const role=String(model?.role||''), defs=(state.definitions||[]).filter(r=>String(r.role||'')===role);
  const table=defs.find(r=>String(r.name||'')===String(model?.name||'') && String(r.nodeType||'')==='table')
    || defs.find(r=>String(r.name||'')===String(model?.name||''));
  if(!table)return '';
  const ti=defs.indexOf(table),td=Number(table.depth)||0;
  let best=null,bestDepth=-1;
  for(let i=ti-1;i>=0;i--){
    const r=defs[i],d=Number(r.depth)||0;
    if(d>=td)continue;
    if(String(r.nodeType||'')==='abstract' && d>bestDepth){best=r;bestDepth=d;if(d===td-1)break;}
    if(d===0 && best)break;
  }
  return best?`${best.prefix}:${best.name}`:'';
}
function v22TablesForAbstract(hostRole,abstractQ){
  const out=[];
  for(const model of v15TableModels(hostRole)){
    if(v22TableHostRole(model)!==String(hostRole))continue;
    if(v22TableAbstractQ(model)===String(abstractQ))out.push(model);
  }
  return out;
}

function factRow(r,i,role){const k=`${r.prefix}:${r.name}`;const e=v18Element(k)||{};const val=state.values[k]??'';const prior=state.prior[k]??'';const dimensional=conceptHasDimensionalTable(k,role)||conceptHasAnyDimensionalTable(k)||(state.priorFacts?.[k]||[]).some(o=>o.context?.dimensions?.length)||(state.factOccurrences?.prior||[]).some(o=>o.concept===k&&o.context?.dimensions?.length);const dimmed=dimensional;const pad=Math.min(Number(r.depth||0),8)*14;const isAbs=e.abstract==='true';const bad=state.cellIssues?.[k];const anchoredTables=isAbs?v22TablesForAbstract(role,k):[];const disabled=isDisabledConcept(k,e,role,false), priorDisabled=isDisabledConcept(k,e,role,true);const calc=preferredCalculationCandidate(k,'current');const calcHint=disabled&&calc?`<div class="calc-hint"><b>Auto total:</b> ${esc(calc.children.map(c=>`${c.label||c.q}${Number(c.weight)===-1?' (subtract)':''}`).join(' + '))}. Applies to Current &amp; Previous Year; edit in Tag / details.</div>`:'';return `<tr data-concept-row="${esc(k)}"><td><div style="padding-left:${pad}px" class="tree-label">${esc(r.label||e.label||r.name)}</div><div class="hint code">${esc(k)}</div>${e.comment?`<div class="hint">${esc(e.comment)}</div>`:''}${anchoredTables.map(m=>{const ta=v22TableApplicable(role,m,'current')!==false;return `<div class="link-badge"><span class="tag">${esc(String(m.label||m.name||'').replace(/\s*\[Table\]\s*$/i,''))}</span> <button class="smallbtn primary" data-v22-open="${esc(v15Pack(role,m.id))}" ${ta?'':'disabled title="Disabled because the controlling MCA disclosure question is No or not yet selected."'}>See dimensional table</button>${ta?'':'<span class="hint">Not applicable — enable by selecting Yes in the controlling question.</span>'}</div>`;}).join('')}${dimmed?`<div class="link-badge">Dimensional disclosure • <button class="smallbtn" data-v15-open="${esc(v15Pack(role,(v15TableForConcept(role,k)||{}).id||''))}">Open dimensional table</button></div>`:''}${calcHint}${sharedRoles(k).length>1?`<div class="link-badge">Linked across: ${esc(sharedRoles(k).slice(0,3).join(' • '))}</div>`:''}${disabled?`<div class="hint">Auto-linked / disabled</div>`:''}</td><td>${isAbs?'<span class="muted">Heading</span>':(dimensional?`<button class="smallbtn primary" data-v15-open="${esc(v15Pack(role,(v15TableForConcept(role,k)||{}).id||''))}">See dimensional table</button>`:factInput(k,e,val,bad,disabled))}</td><td>${isAbs?'<span class="muted">—</span>':(dimensional?`<button class="smallbtn" data-v15-open="${esc(v15Pack(role,(v15TableForConcept(role,k)||{}).id||''))}">See dimensional table</button>`:(isRichTextConcept(e)?richTextCell(`prior:${k}`,state.priorRichText?.[k]||prior,bad,priorDisabled):isBooleanConcept(e)?yesNoCell(`prior:${k}`,prior,bad,priorDisabled):`<input class="auto-grow prior-cell${priorDisabled?' linked-disabled':''}" value="${esc(prior)}" data-prior="${esc(k)}" placeholder="Prior-year value" ${priorDisabled?'disabled':''}>`))}</td><td><span class="tag">${esc((e.type||'').replace(/^.*:/,''))}</span>${dimensional?'<span class="tag">Dimensional table</span>':''}${isBooleanConcept(e)?'<span class="tag yesno-tag">Yes / No</span>':''}${isRichTextConcept(e)?'<span class="tag">Rich text</span>':''}${e.periodType?`<span class="tag">${e.periodType}</span>`:''}${e.balance?`<span class="tag">${e.balance}</span>`:''}</td><td><button class="smallbtn" data-tag="${esc(k)}">Tag / details</button></td></tr>`}
